INSERT INTO game_role_focus VALUES('FC26','cb_wideback','Defend','Wide Back','With a Defend focus, the Wide Back will cover for the fullbacks in all phases but stay close to the defensive line.','["Cover Side", "Stays Back"]','["Defending"]','["Limited Versatility"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0000000000000000000063X36','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인');
INSERT INTO game_role_focus VALUES('FC26','cb_wideback','Aggressive','Wide Back','With an Aggressive focus, the Wide Back will also close down opponents and intercept passes during the defensive phase.','["Cover Side", "Aggressiveness"]','["Defending"]','["Leaves Gaps"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0000000000000003303363X36','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인');
INSERT INTO game_role_focus VALUES('FC26','cb_wideback','Support','Wide Back','With a Support focus, the Wide Back will move up the side of the pitch to a pass option when their team needs to release pressure.','["Cover Side", "Build-Up Support"]','["Defending"]','["Out of Position"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0000000000300036000663X36','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인');
