INSERT INTO game_role_focus VALUES('FC26','dm_widehalf','Build-Up','Wide Half','When set to Build-Up, the Wide Half can move into the Wingback position, and forward into Wide Midfielder territory, when their team is in possession.','["Pass Option", "Wide Support"]','["Supports the Defence"]','["Supports Centrally"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0000000000300036363600000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인');
INSERT INTO game_role_focus VALUES('FC26','dm_widehalf','Defend','Wide Half','When instructed to Defend, the Wide Half can drop into Fullback and Wingback positions while their team has the ball.','["Defending", "Wide Support"]','["Stays Back"]','["Supports Centrally"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0000000000000006363630003','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인');
INSERT INTO game_role_focus VALUES('FC26','cam_classic10','Versatile','Classic 10','When set to Versatile, the Classic 10 will use their best judgement when determining if they should stay central or use the pitch''s width during attacks.','["Dynamic Width", "Creative"]','["Supports Attacks"]','["Out of Position"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0000066X66000000000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인');
INSERT INTO game_role_focus VALUES('FC26','cam_classic10','Wide','Classic 10','When set to Wide, the Classic 10 is able to drift out to the wing, and dictate attacks from anywhere across the width of the pitch.','["Supports Attacks", "Creative"]','["Wide Support"]','["Supports the Defence"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0000036X63000000000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인');
