INSERT INTO game_role_focus VALUES('FC26','st_target','Attack','Target Forward','With an Attack focus, the Target Forward is free to focus on going forward, without any defensive instructions.','["Physical", "Attacking"]','["Build-Up Support"]','["Lacks Mobility"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','03X3000000000000000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인');
INSERT INTO game_role_focus VALUES('FC26','st_target','Balanced','Target Forward','When Balanced, the Target Forward will drop off from the defensive line, hold up play, and lay the ball off to teammates. They will have minor defensive duties.','["Physical", "Build-Up Support"]','["Defense Support"]','["Lacks Mobility"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','00X0000600000000000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인');
INSERT INTO game_role_focus VALUES('FC26','st_target','Wide','Target Forward','When set to Wide, the Target Forward will drift to the edges of the box in a search for space to make an impact.','["Physical", "Wide Support"]','["Attacking"]','["Support Centrally"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','6636600000000000000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인');
