INSERT INTO game_role_focus VALUES('FC26','st_advanced','Attack','Advanced Forward','With an Attack focus, the Advanced Forward will concentrate on goal-scoring opportunities, usually positioning themselves high and central on the pitch.','["Attacking", "Pass Option"]','["Versatile"]','["Limited Width"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','06X6000300000000000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인');
