INSERT INTO game_role_focus VALUES('FC26','w_wideplm','Build-Up','Wide Playmaker','When set to Build-Up, the Wide Playmaker will come short to offer a passing option, while balancing their approach to support the defence if needed.','["Creative", "Build-Up Support"]','["Supports the Defence"]','["Support Centrally"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','33000X6000600000000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인');
INSERT INTO game_role_focus VALUES('FC26','w_insidefwd','Attack','Inside Forward','When given an Attack focus, the Inside Forward will focus on cutting inside and making attacking runs.','["Attacking", "Support Centrally"]','["Cut Inside"]','["Defence Support"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0X60036300000000000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인');
INSERT INTO game_role_focus VALUES('FC26','w_insidefwd','Balanced','Inside Forward','When Balanced, the Inside Forward will offer minimal defensive support, and sometimes hold off making runs in behind to instead offer passing options.','["Attack Support", "Pass Option"]','["Cut Inside"]','["Stamina Usage"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','063006X300330000000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인');
INSERT INTO game_role_focus VALUES('FC26','w_insidefwd','Roaming','Inside Forward','When set to Roaming, the inside Forward is allowed to freely explore and exploit any defensive gaps they can find.','["Movement", "Attack Support"]','["Cut Inside"]','["Out of Position"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','363003X600300000000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인');
INSERT INTO game_role_focus VALUES('FC26','w_winger','Versatile','Winger','The Versatile Winger decides when it''s the right opportunity to attack or defend, and they can swap sides with another Versatile Winger between phases of play.','["Supports Play", "Wide Support"]','["Out of Position"]','["Stamina Usage"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','X6000X0000600003000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인');
INSERT INTO game_role_focus VALUES('FC26','w_winger','Attack','Winger','When set to Attack, the Winger will focus on getting forward, and prefers to make runs behind the defence instead of receiving the ball to feet.','["Wide Support", "Supports Attacks"]','["Pass Option"]','["Defending"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','X3000X0000300000000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인');
INSERT INTO game_role_focus VALUES('FC26','w_winger','Balanced','Winger','When Balanced, the Winger will offer both defensive and attacking support. They mix making runs behind and offering themselves as a passing option.','["Wide Support", "Pass Option"]','["Versatile"]','["Stamina Usage"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','60000X0000600003000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인');
INSERT INTO game_role_focus VALUES('FC26','cam_halfwinger','Roaming','Half-Winger','When set to Roaming, this attacking Half-Winger will freely alternate the side on which they attack, even during plays.','["Dynamic Side", "Attacking"]','["Wide Support"]','["Out of Position"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','X000X66366000000000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인');
INSERT INTO game_role_focus VALUES('FC26','cam_halfwinger','Attack','Half-Winger','When set to Attack, the Half Winger can advance freely, sacrificing defensive responsibilities.','["Wide Support", "Attacking"]','["Out of Position"]','["Defence Support"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','6000633333000000000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인');
