INSERT INTO game_role_focus VALUES('FC26','cam_playmaker','Roaming','Playmaker','When set to Roaming, the Playmaker will have freedom to explore the pitch to find the best spaces to support attacks.','["Creative", "Movement"]','["Out of Position"]','["Supports the Defence"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0333006X60033300000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인');
INSERT INTO game_role_focus VALUES('FC26','wm_insidefwd','Balanced','Inside Forward','When Balanced, the Inside Forward will offer minimal defensive support, and sometimes hold off making runs in behind to instead offer passing options.','["Attack Support", "Pass Option"]','["Cut Inside"]','["Stamina Usage"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','063003X600600000000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인');
INSERT INTO game_role_focus VALUES('FC26','wm_insidefwd','Attack','Inside Forward','When given an Attack focus, the Inside Forward will focus on cutting inside and making attacking runs.','["Attacking", "Support Centrally"]','["Cut Inside"]','["Defence Support"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0X60036300300000000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인');
INSERT INTO game_role_focus VALUES('FC26','wm_wideplm','Attack','Wide Playmaker','With an Attack focus, the Wide Playmaker will move forward, and receive passes out wide.','["Creative", "Attack Support"]','["Wide Support"]','["Defence Support"]',1,'좌우 표기차(동의어) — L채택: R={p:[Creative,Supports Attacks],e:[Wide Support],n:[Supports the Defence]}','fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0000066000330000000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인');
INSERT INTO game_role_focus VALUES('FC26','wm_wideplm','Build-Up','Wide Playmaker','When set to Build-Up, the Wide Playmaker will come short to offer a passing option, while balancing their approach to support the defence if needed.','["Creative", "Build-Up Support"]','["Supports the Defence"]','["Support Centrally"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0000033000660000000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인');
