INSERT INTO game_role_focus VALUES('FC26','cm_b2b','Balanced','Box-To-Box','When asked to be Balanced, the Box-to-box Midfielder will cover the centre of the pitch in attack and defence.','["Attack Support", "Defence Support"]','["Versatile"]','["Stamina Usage"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0030000X0003X3000X0000300','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인');
INSERT INTO game_role_focus VALUES('FC26','dm_dlp','Build-Up','Deep-Lying Playmaker','When set to Build-Up, the Deep-lying Playmaker will move forward and offer a passing option to support attacks.','["Creative", "Versatile"]','["Pass Option"]','["Supports the Defence"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','000000030003X3003X3000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인');
INSERT INTO game_role_focus VALUES('FC26','dm_dlp','Roaming','Deep-Lying Playmaker','The Roaming focus allows the Deep-lying Playmaker to move across the width of the pitch to support attacks.','["Creative", "Movement"]','["Pass Option"]','["Out of Position"]',0,'에메리 프리셋 LDM 만잠비 처방의 1차 근거','fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0000003330066600363000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인');
INSERT INTO game_role_focus VALUES('FC26','dm_dlp','Defend','Deep-Lying Playmaker','With a Defend focus, the Deep-lying Playmaker will focus on closing down passing lanes and staying back while their team attacks.','["Defending", "Creative"]','["Intercepts Passes"]','["Attacking"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','00000000000333003X3000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인');
INSERT INTO game_role_focus VALUES('FC26','dm_centrehalf','Defend','Centre-Half','When set to Defend, the Centre Half will focus on their defensive duties.','["Defending", "Support Centrally"]','["Limited Versatility"]','["Wide Support"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','00000000000000003X3003X30','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인');
INSERT INTO game_role_focus VALUES('FC26','dm_holding','Ball-Winning','Holding','The Ball-Winning focus tasks the Holding Midfielder with aggressively intercepting passing as part of their defensive focus.','["Defending", "Aggressiveness"]','["Limited Versatility"]','["Pass Option"]',0,'에메리 프리셋 RDM 카마라 처방의 1차 근거 — negative가 Pass Option인 것이 obs#32의 ''창조 전무'' 실측과 정합','fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','00000000000000006X6000300','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인');
INSERT INTO game_role_focus VALUES('FC26','dm_holding','Roaming','Holding','When set to Roaming, the Holding Midfielder will move across the width of the pitch to close passing lanes, and step up to press attackers.','["Defending", "Movement"]','["Pass Option"]','["Stamina Usage"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0000000000033306XXX600000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인');
INSERT INTO game_role_focus VALUES('FC26','dm_holding','Defend','Holding','When instructed to Defend, the Holding Midfielder will move slightly higher to offer a passing option, but will otherwise focus on defending.','["Defending", "Stays Back"]','["Pass Option"]','["Lacks Mobility"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','00000000000030003X3000300','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인');
INSERT INTO game_role_focus VALUES('FC26','cb_bpd','Aggressive','Ball-Playing Defender','When asked to be Aggressive, the Ball-Playing Defender will focus on intercepting passes and closing down opponents.','["Pressure", "Aggressiveness"]','["Build-Up Support"]','["Leaves Gaps"]',0,'에메리 프리셋 RCB 콘사 처방의 1차 근거 — obs#17 ''스텝아웃'' 실측과 정합','fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','00000000000363006X6003630','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인');
INSERT INTO game_role_focus VALUES('FC26','cb_bpd','Build-Up','Ball-Playing Defender','The Build-Up focus moves the Ball-playing Defender into more of a holding defensive midfielder during possession.','["Build-Up Support", "Defence Support"]','["Versatile"]','["Out of Position"]',0,'에메리 프리셋 LCB 파우 토레스 처방의 1차 근거','fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','00000000000030006X6006X60','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인');
INSERT INTO game_role_focus VALUES('FC26','cb_bpd','Defend','Ball-Playing Defender','When set to Defend, the Ball-playing Defender will step up a little to support teammates during possession.','["Defending", "Build-Up Support"]','["Stays Back"]','["Leave Gaps"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0000000000000000363006X60','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인');
