INSERT INTO game_role_focus VALUES('FC26','fb_att_wb','Attack','Attacking Wingback','When asked to Attack, the Attacking Wingback will push even higher up the pitch, and perform fewer defensive duties.','["Attacking", "Wide Support"]','["Out of Position"]','["Defending"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','X000060000300003000030000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인');
INSERT INTO game_role_focus VALUES('FC26','fb_att_wb','Support','Attacking Wingback','When asked to Support, the Attacking Wingback will rarely sprint back to defend, unless their team has been hit on the counter.','["Wide Support", "Attacking"]','["Stamina Usage"]','["Defending"]',0,'⚠️ 에메리 프리셋 LB 에스투피냔·RB 보가르드 처방. negative가 Defending인 것이 C2(풀백 한 명씩 전진) 붕괴의 1차 근거 — 양쪽 풀백을 이 포커스로 두면 두 측면 모두 수비 복귀가 negative가 된다','fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','30000X0000600006000030000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인');
INSERT INTO game_role_focus VALUES('FC26','fb_wingback','Support','Wingback','When asked to Support, the Wingback can only attack when their team has controlled possession, and only defend when the team doesn''t have the ball.','["Wide Support", "Defence Option"]','["Out of Position"]','["Stamina Usage"]',0,'C2 비대칭 복원 옵션 — plus에 Defence Option이 있어 att_wb/Support(neg: Defending)와 정확히 대비된다','fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0000030000X60006000060000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인');
INSERT INTO game_role_focus VALUES('FC26','fb_wingback','Balanced','Wingback','With Balanced, the Wingback is given license to stay forward even when the team is out of possession, or drop back into defence when needed.','["Wide Support", "Movement"]','["Versatile"]','["Stamina Usage"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0000030000X0000X000060000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인');
